select public.assert_journey(not has_table_privilege('authenticated','private.xooter_journey_events','select'),'private event reads closed');
select public.assert_journey(not has_table_privilege('service_role','private.xooter_journey_events','insert'),'service cannot forge events');
select public.assert_journey(not has_function_privilege('anon','public.manage_xooter_communications(text,jsonb,integer)','execute'),'anonymous manager denied');
select public.assert_journey(not has_function_privilege('authenticated','private.collect_xooter_journeys(timestamptz)','execute'),'client cannot run scheduler');
select public.assert_journey(not has_function_privilege('service_role','private.emit_xooter_journey(uuid,text,text)','execute'),'service cannot arbitrarily choose recipients');
set role authenticated;
select public.expect_journey_error($$select public.manage_xooter_communications('start')$$,'42501');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
select public.expect_journey_error($$select public.manage_xooter_communications('start')$$,'42501');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
select public.assert_journey(public.manage_xooter_communications('start')->>'tips'='false','tips default off');
select public.assert_journey(public.manage_xooter_communications('start')->>'promotions'='false','promotions default off');
select public.assert_journey(public.manage_xooter_communications('get')->>'email_updates'='true','status email choice defaults on');
select public.expect_journey_error($$select public.manage_xooter_communications('save','{"email_updates":true,"onboarding_reminders":true,"tips":true,"promotions":true,"user_id":"another"}',0)$$,'22023');
select public.expect_journey_error($$select public.manage_xooter_communications('save','{"email_updates":true,"onboarding_reminders":true,"tips":"true","promotions":true}',0)$$,'22023');
select public.assert_journey(public.manage_xooter_communications('save','{"email_updates":true,"onboarding_reminders":false,"tips":false,"promotions":false}',0)->>'revision'='1','preference change is confirmed');
select public.expect_journey_error($$select public.manage_xooter_communications('save','{"email_updates":true,"onboarding_reminders":true,"tips":true,"promotions":true}',0)$$,'40001');
reset role;
select public.assert_journey((select count(*)=1 from private.xooter_journey_events),'welcome deduplicated across visits');
select public.assert_journey((select count(*)=1 from public.notifications),'welcome is an actual notification');
select public.assert_journey((select count(*)=1 from public.integration_outbox),'one matching email queue record');
select public.assert_journey((select bool_and(payload=jsonb_build_object('journey_event_id',source_id)) from public.integration_outbox),'outbox carries no recipient or screening content');
select public.assert_journey(not exists(select from private.xooter_communication_preferences where user_id='00000000-0000-4000-8000-000000000002'),'no other-user preferences created');
update private.xooter_journeys set started_at=clock_timestamp()-interval '4 days';
select private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours');
select public.assert_journey((select count(*)=1 from public.notifications),'opt-out stops onboarding reminders');
set role authenticated;
select public.assert_journey(public.manage_xooter_communications('save','{"email_updates":true,"onboarding_reminders":true,"tips":false,"promotions":false}',1)->>'revision'='2','reminders can be enabled');
reset role;
select public.assert_journey(private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '22 hours')=0,'Johannesburg midnight quiet hours');
select public.assert_journey(private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours')=2,'two overdue reminders maximum');
select public.assert_journey(private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours')=0,'repeated scheduler emits no duplicates');
insert into public.xooter_applications(user_id,status) values('00000000-0000-4000-8000-000000000002','submitted');
select public.assert_journey((select count(*)=1 from public.notifications where user_id='00000000-0000-4000-8000-000000000002' and kind='xooter_application_received'),'actual submission emits status atomically');
insert into public.notifications(user_id,kind,title,body) values('00000000-0000-4000-8000-000000000002','xooter_application_submitted','Legacy duplicate','Legacy body');
select public.assert_journey(not exists(select from public.notifications where kind='xooter_application_submitted'),'migration rollout omits the old handler duplicate');
insert into public.integration_outbox(source_table,source_id,event_type,channel,owner,stack_tool,payload,status,approval_required)
  select 'xooter_applications',id,'trust_verification_update','brevo_email','Legacy','Legacy','{}','queued',false
  from public.xooter_applications where user_id='00000000-0000-4000-8000-000000000002';
select public.assert_journey(not exists(select from public.integration_outbox where event_type='trust_verification_update'),'migration rollout omits the old email preparation');
update private.xooter_journeys set started_at=clock_timestamp()-interval '4 days' where user_id='00000000-0000-4000-8000-000000000002';
select private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours');
select public.assert_journey(not exists(select from private.xooter_journey_events where user_id='00000000-0000-4000-8000-000000000002' and kind like 'xooter_continue_%'),'submitted applicant gets no unfinished reminder');
update public.xooter_applications set status='submitted';
select public.assert_journey((select count(*)=1 from public.notifications where kind='xooter_application_received'),'same-status writes are idempotent');
update public.xooter_applications set status='rejected';
select public.assert_journey((select count(*)=1 from public.notifications where kind='xooter_application_attention'),'needs-attention update delivered');
insert into public.notifications(user_id,kind,title,body) values('00000000-0000-4000-8000-000000000002','xooter_application_rejected','Legacy duplicate','Legacy body');
select public.assert_journey(not exists(select from public.notifications where kind='xooter_application_rejected'),'rollback legacy rejection notification remains deduplicated');
update public.xooter_applications set status='submitted';
select public.assert_journey((select count(*)=2 from public.notifications where kind='xooter_application_received'),'real resubmission gets its own receipt');
update public.xooter_applications set status='approved';
select private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours');
select public.assert_journey(not exists(select from public.notifications where kind='xooter_onboarding_complete'),'approved label alone does not claim activated supply');
insert into public.xooters(user_id,active) values('00000000-0000-4000-8000-000000000002',true);
select private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours');
select public.assert_journey(not exists(select from public.notifications where kind='xooter_onboarding_complete'),'active row without role still insufficient');
insert into public.user_roles(user_id,role) values('00000000-0000-4000-8000-000000000002','xooter');
select public.assert_journey(private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours')=1,'actual approval active profile and role give completion');
select public.assert_journey(private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours')=0,'completion once only');
update private.xooter_journeys set approved_at=clock_timestamp()-interval '20 days';
select private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours');
select public.assert_journey(not exists(select from private.xooter_journey_events where optional),'no tips without consent');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
select public.assert_journey(public.manage_xooter_communications('save','{"email_updates":true,"onboarding_reminders":false,"tips":true,"promotions":false}',0)->>'tips'='true','tips explicit consent recorded');
reset role;
select public.assert_journey((select tips_consented_at is not null and promotions_consented_at is null from private.xooter_communication_preferences where user_id='00000000-0000-4000-8000-000000000002'),'separate dated consent');
select public.assert_journey(private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours')=1,'one useful tip');
select public.assert_journey(private.collect_xooter_journeys(date_trunc('day',clock_timestamp())+interval '10 hours')=0,'optional seven-day frequency cap');
set role authenticated;
select public.assert_journey(public.manage_xooter_communications('save','{"email_updates":false,"onboarding_reminders":false,"tips":false,"promotions":false}',1)->>'tips'='false','optional messages can be turned off');
reset role;
select public.assert_journey((select tips_consented_at is null from private.xooter_communication_preferences where user_id='00000000-0000-4000-8000-000000000002'),'revoked consent date cleared');
select public.assert_journey(not exists(select from public.user_roles where user_id='00000000-0000-4000-8000-000000000001'),'welcome never grants Xooter role');
select public.assert_journey((select count(*) from private.xooter_journey_events)=(select count(*) from public.notifications),'all accepted events have durable notifications');
select public.assert_journey((select count(*) from private.xooter_journey_events)=(select count(*) from public.integration_outbox),'all events have distinct email preparations');
select public.assert_journey((select bool_and(email_state='queued') from private.xooter_journey_events),'queue does not assert delivery');
